use super::*;
use super::super::StringsTraversal::{StringsTraversal,Blocks};
use serde_json::{json,Value};
use std::panic::{catch_unwind,AssertUnwindSafe};
fn call<T:serde::Serialize>(f:impl FnOnce()->T)->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>{let t=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");let result=["IllegalStateException","NumberFormatException","ArrayIndexOutOfBoundsException","NullPointerException"].iter().find(|n|t.starts_with(**n)).copied().unwrap_or(t);json!({"result":result})}}}
fn blocks(bs:Option<&Blocks>)->Value{let mut rows=vec![];if let Some(bs)=bs{for b in bs.borrow().iter(){rows.push(json!({"mBeginIndex":b.mBeginIndex.get(),"mEndIndex":b.mEndIndex.get(),"mBeginOffset":b.mBeginOffset.get(),"mEndOffset":b.mEndOffset.get(),"bNeedReadFirst":b.bNeedReadFirst.get(),"bHasRead":b.bHasRead.get()}));}}json!(rows)}
fn root()->std::path::PathBuf{std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("rewrite-review/milestones/m4-edit-save/evidence/sst-blocks-r0b45")}
fn read(name:&str)->Value{serde_json::from_slice(&std::fs::read(root().join(name)).unwrap()).unwrap()}
#[test]
fn original_android_sst_byte_traversal(){let input=read("inputs.json");let java=read("java.json");let mut rows=vec![];for(i,p)in input["sst"].as_array().unwrap().iter().enumerate(){let path=root().join(format!("native-traverse-{i}.xml"));std::fs::write(&path,p["xml"].as_str().unwrap()).unwrap();let bs=Rc::new(RefCell::new(vec![]));let t=StringsTraversal::StringsTraversal(Some(path.to_str().unwrap().into()),Some(bs.clone()));let mut row=call(||{t.traversal().unwrap();Value::Null});row["unique"]=json!(t.getUniqueCount());row["text"]=json!(t.toString());row["blocks"]=blocks(Some(&bs));assert_eq!(row,java["traversals"][i],"case {i}");rows.push(row);}std::fs::write(root().join("rust-traversals.json"),serde_json::to_vec_pretty(&rows).unwrap()).unwrap();}
pub(crate) fn snapshot(book:&KmoBook,indices:&Value)->Value{let state=SST_STATIC.borrow();let bs=state.mBlocks.clone();let path=state.mStringPath.clone();drop(state);let strings:Vec<_>=indices.as_array().unwrap().iter().map(|i|call(||book.getCellValueStore().borrow_mut().getStringBySSTId(i.as_i64().unwrap()as i32))).collect();json!({"unique":XlsxrSharedStrings::getUniqueCount(),"storeCount":book.getCellValueStore().borrow().getUniqueCount(),"blocksNull":bs.is_none(),"blocks":blocks(bs.as_ref()),"pathNull":path.is_none(),"cacheExists":path.as_ref().is_some_and(|s|std::path::Path::new(s).exists()),"strings":strings})}
fn pipeline(book:&Rc<KmoBook>,p:&Value,index:usize)->Value{use crate::cn::wps::moss::engine::grid::KmoCellValueStore::KmoCellValueStore;use kfc_kfc_alpha::kfc::opcr::{ZipFile::ZipFile,OpcrRelationships::OpcrRelationships};*book.getCellValueStore().borrow_mut()=KmoCellValueStore::KmoCellValueStore();let zip=ZipFile::from_path(root().join("zips").join(format!("source-{index}.zip")).to_str().unwrap()).unwrap();let mut rels=OpcrRelationships::OpcrRelationships(&zip,"xl/workbook.xml").unwrap();let mut r=json!({"open":call(||{XlsxrSharedStrings::open(book,rels.getRelationship__rid_mut(Some("rIdS"))).unwrap();Value::Null}),"afterOpen":snapshot(book,&p["indices"])});for i in p["first"].as_array().unwrap(){XlsxrSharedStrings::onSheetStringIndex(i.as_i64().unwrap()as i32);}r["afterMarks"]=snapshot(book,&p["indices"]);r["before"]=call(||{XlsxrSharedStrings::onActiveSheetBefore(book).unwrap();Value::Null});r["afterBefore"]=snapshot(book,&p["indices"]);r["after"]=call(||{XlsxrSharedStrings::onActiveSheetAfter(book).unwrap();Value::Null});r["afterAfter"]=snapshot(book,&p["indices"]);r}
#[test]
fn original_android_sst_blocks_before_after_and_cleanup(){use crate::cn::wps::moss::app::KmoBookApi::KmoBookApi;let input=read("inputs.json");let java=read("java.json");let api=KmoBookApi::KmoBookApi();let fixture=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("rewrite-review/milestones/m1-xlsx-grid-read/fixtures/basic-types.xlsx");assert_eq!(api.open(fixture.to_str().unwrap(),None,true),1);std::thread::sleep(std::time::Duration::from_millis(1000));let book=api.book();let rows:Vec<_>=input["sst"].as_array().unwrap().iter().enumerate().map(|(i,p)|pipeline(&book,p,i)).collect();std::fs::write(root().join("rust-pipelines.json"),serde_json::to_vec_pretty(&rows).unwrap()).unwrap();fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}compare(&json!(rows),&java["pipelines"],"root");}
#[test]
fn original_rich_text_run_alias_and_inner_owner(){
    use crate::cn::wps::moss::xlsxr::handler::sheet::RichTextHandler::RichTextHandler;
    use kfc_kfc_alpha::kfc::xpxml::reader::XmlRoAttrList::XmlRoAttrList;
    let book=KmoBook::KmoBook();let strs=Rc::new(RefCell::new(vec![]));let h=RichTextHandler::RichTextHandler(Some(strs.clone()),book.clone());let attrs=XmlRoAttrList::new();h.startElement(4649,&attrs);let r1=h.enterSubElement(4151).unwrap();let r2=h.enterSubElement(4151).unwrap();r1.startElement(4151,&attrs);let text=r1.enterSubElement(4155).unwrap();text.startElement(4155,&attrs);text.characters("same run");r2.endElement(4151);h.endElement(4649);assert_eq!(strs.borrow()[0].getString(),"same run");
    let held=RichTextHandler::RichTextHandler(Some(strs.clone()),book);let weak=Rc::downgrade(&held);held.startElement(4649,&attrs);let text=held.enterSubElement(4155).unwrap();drop(held);assert!(weak.upgrade().is_some());text.characters("retained value");weak.upgrade().unwrap().endElement(4649);assert_eq!(strs.borrow()[1].getString(),"retained value");drop(text);assert!(weak.upgrade().is_none());
}
